INSERT INTO books (bookid, isbn, title, publisher, price, description, publish_date, cover_image, quantity) VALUES
    (1, 2908, N'Nghệ Thuật Thể Hiện Ánh Sáng Và Màu Sắc', N'NXB Trẻ', 34000.00, N'Nghệ Thuật Thể Hiện Ánh Sáng Và Màu Sắc Đây là bộ sách cẩm nang tuyệt vời dành cho các bạn đang bắt đầu học vẽ truyện tranh. Những kiến thức này có thể không giúp các bạn vẽ đẹp ngay lập tức nhưng sẽ là nền tảng vững chắc giúp bạn hình thành các tiêu chuẩn chuyên nghiệp trong nghề và không mất thời gian tự mò mẫm. Phần minh họa cho các bài học cũng rất hấp dẫn và sáng tạo. Các tác giả đã sử dụng chính nhân vật và trang truyện của mình để làm rõ sự liên quan giữa lý thuyết và thực tế, tính ứng dụng rõ ràng của các kỹ thuật và quy trình sáng tác. Trên thị trường hiện tại không thiếu những quyển sách dạy vẽ truyện tranh được dịch và biên tập lại từ nhiều nguồn nhưng đa số là kiểu sách “cầm tay chỉ việc”, không thật sữ hữu ích với các bạn trẻ Việt Nam – những bạn không theo học chuyên ngành mỹ thuật, thiếu kiến thức nền tảng về hội họa… Ngược lại, trong bộ sách Vẽ Truyện Tranh Phong Cách Nhật Bản, mọi phần kiến thức từ lớn đến nhỏ đều được lý giải và phân tích khá kỹ kèm ảnh minh họa rõ ràng, giúp người xem hiểu được gốc rễ vấn đề đồng thời áp dụng áp dụng vào nhiều “ngữ cảnh” khác nhau trong lúc sáng tác. Giá sản phẩm trên Tiki đã bao gồm thuế theo luật hiện hành. Bên cạnh đó, tuỳ vào loại sản phẩm, hình thức và địa chỉ giao hàng mà có thể phát sinh thêm chi phí khác như phí vận chuyển, phụ phí hàng cồng kềnh, thuế nhập khẩu (đối với đơn hàng giao từ nước ngoài có giá trị trên 1 triệu đồng).....', '2015-10-04', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935088534180_1.jpg', 50),
    (2, 2909, N'Tạo Hình Nhân Vật Truyện Tranh Với Động Tác Và Trang Phục Đặc Biệt', N'NXB Kim Đồng', 31000.00, N'Chưa có', '2024-03-01', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_20368.jpg', 50),
    (3, 2911, N'Tạo Hình Nhân Vật Nữ Duyên Dáng', N'NXB Văn học', 29000.00, N'Tạo Hình Nhân Vật Nữ Duyên Dáng', '2019-09-11', N'https://cdn1.fahasa.com/media/catalog/product/2/9/2911.jpg', 50),
    (4, 2912, N'Phác Thảo Ngoại Hình Nhân Vật Thiếu Nữ Trong Truyện Tranh', N'NXB Thế giới', 29000.00, N'Đây là bộ sách cẩm nang tuyệt vời dành cho các bạn đang bắt đầu học vẽ truyện tranh. Những kiến thức này có thể không giúp các bạn vẽ đẹp ngay lập tức nhưng sẽ là nền tảng vững chắc giúp bạn hình thành các tiêu chuẩn chuyên nghiệp trong nghề và không mất thời gian tự mò mẫm. Phần minh họa cho các bài học cũng rất hấp dẫn và sáng tạo. Các tác giả đã sử dụng chính nhân vật và trang truyện của mình để làm rõ sự liên quan giữa lý thuyết và thực tế, tính ứng dụng rõ ràng của các kỹ thuật và quy trình sáng tác. Trên thị trường hiện tại không thiếu những quyển sách dạy vẽ truyện tranh được dịch và biên tập lại từ nhiều nguồn nhưng đa số là kiểu sách “cầm tay chỉ việc”, không thật sữ hữu ích với các bạn trẻ Việt Nam – những bạn không theo học chuyên ngành mỹ thuật, thiếu kiến thức nền tảng về hội họa… Ngược lại, trong bộ sách Vẽ Truyện Tranh Phong Cách Nhật Bản, mọi phần kiến thức từ lớn đến nhỏ đều được lý giải và phân tích khá kỹ kèm ảnh minh họa rõ ràng, giúp người xem hiểu được gốc rễ vấn đề đồng thời áp dụng áp dụng vào nhiều “ngữ cảnh” khác nhau trong lúc sáng tác.', '2020-01-01', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_20371.jpg', 50),
    (5, 2916, N'Tạo Hình Nhân Vật Và Bối Cảnh Trong Truyện Tranh Hoạt Hình', N'NXB Lao Động', 19000.00, N'Đây là bộ sách cẩm nang tuyệt vời dành cho các bạn đang bắt đầu học vẽ truyện tranh. Những kiến thức này có thể không giúp các bạn vẽ đẹp ngay lập tức nhưng sẽ là nền tảng vững chắc giúp bạn hình thành các tiêu chuẩn chuyên nghiệp trong nghề và không mất thời gian tự mò mẫm. Phần minh họa cho các bài học cũng rất hấp dẫn và sáng tạo. Các tác giả đã sử dụng chính nhân vật và trang truyện của mình để làm rõ sự liên quan giữa lý thuyết và thực tế, tính ứng dụng rõ ràng của các kỹ thuật và quy trình sáng tác. Trên thị trường hiện tại không thiếu những quyển sách dạy vẽ truyện tranh được dịch và biên tập lại từ nhiều nguồn nhưng đa số là kiểu sách “cầm tay chỉ việc”, không thật sữ hữu ích với các bạn trẻ Việt Nam – những bạn không theo học chuyên ngành mỹ thuật, thiếu kiến thức nền tảng về hội họa… Ngược lại, trong bộ sách Vẽ Truyện Tranh Phong Cách Nhật Bản , mọi phần kiến thức từ lớn đến nhỏ đều được lý giải và phân tích khá kỹ kèm ảnh minh họa rõ ràng, giúp người xem hiểu được gốc rễ vấn đề đồng thời áp dụng áp dụng vào nhiều “ngữ cảnh” khác nhau trong lúc sáng tác.', '2018-08-17', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_20373.jpg', 50),
    (6, 2917, N'Phác Thảo Nhân Vật Qua Trang Phục', N'NXB Hội nhà văn', 18000.00, N'Chưa có', '2021-11-14', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935088534210_1.jpg', 50),
    (7, 2982, N'Sách Hướng Dẫn Kỹ Năng Học Tập Theo Phương Pháp Buzan', N'NXB Tổng hợp TP.HCM', 164000.00, N'Bộ não của bạn là một bộ xử lý siêu mạnh có khả năng tạo ra vô số ý tưởng liên kết nhau. Nếu bạn biết cách khai thác nó thì học tập sẽ không còn là công việc đầy lo âu và căng thẳng mà trở nên nhanh chóng, dễ dàng và hiệu quả. Sách hướng dẫn kỹ năng học tập theo phương pháp Buzan sẽ giúp bạn: * Tìm ra con đường học tập hiệu quả nhất * Có khả năng đọc 1.000 từ mỗi phút * Nâng cao khả năng tập trung và hiểu * Ghi chú hiệu quả hơn khi nghe giảng và đọc * Ghi nhớ và nhớ lại hiệu quả nội dung đã học * Ôn tập một cách khoa học nhưng vẫn có những phút “giải lao” thoải mái * Tự tin chuẩn bị cho việc học, thi cử và kiểm tra Tony Buzan, người phát minh Sơ đồ tư duy, là chuyên gia hàng đầu thế giới về não bộ và phương pháp học tập. Hơn 35 năm qua, Tony Buzan đã hoạt động không mệt mỏi giúp mọi người ở các độ tuổi khác nhau trên toàn thế giới tận dụng tối đa khả năng tư duy của họ bằng việc áp dụng các kỹ thuật lập Sơ đồ tư duy, Đọc nhanh và nhớ. Trong sách hướng dẫn này, tác giả kết hợp những kỹ thuật trên với chương trình Bost độc đáo để giúp người học ở mọi trình độ tiếp cận một phương pháp học mới và hoàn toàn tích cực. Bằng việc thực hành chúng, bạn sẽ tự tin hơn và kỹ năng phát huy năng lực học tập của bản thân qua đó cũng phát triển, dù bạn học môn gì hay ở trình độ nào.', '2024-08-18', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_20375.jpg', 50),
    (8, 2998, N'Xì Xầm vs Hét To - Bí Kíp X Trong Quảng Cáo-PR', N'NXB Phụ nữ', 50000.00, N'Bạn có biết những người sáng lập eBay không hề chi một đồng cho quảng cáo, ngoài các hoạt động PR kéo dài trong hai năm - điều giúp họ thu hút vốn, đối tác, nhân viên và các khách hàng tiềm năng? Thật vậy, các chiến dịch PR có khả năng mở ra những thị trường mới và cho phép bạn xây dựng nên thương hiệu cho sản phẩm của bạn, và cho chính bản thân bạn. Cuốn sách "Xì Xầm Vs Hét To - Bí Kíp X Trong Quảng Cáo PR" sẽ giúp bạn thiết lập vị thế thị trường cho doanh nghiệp của bạn và tối đa hóa doanh số, thông qua các hoạt động PR đơn giản như: Tiếp cận với đối tượng truyền thông mục tiêu của bạn; Truyền đạt các thông điệp chính; Tạo sự khác biệt giữa doanh nghiệp của bạn và các đối thủ; Tạo vị thế quan trọng cho doanh nghiệp của bạn trong ngành; ...', '2019-04-03', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935086827192_3.jpg', 50),
    (9, 3022, N'Quản Lý Toàn Cầu- Managing Globally', N'NXB Trẻ', 18000.00, N'Quản Lý Toàn Cầu- Managing Globally', '2019-02-01', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935086804544_1.jpg', 50),
    (10, 3441, N'101 Hướng Dẫn Thực Tế Hữu Ích khi Mang Thai & Sinh Nở', N'NXB Kim Đồng', 24000.00, N'101 Hướng dẫn thực tế và hữu ích: Mang thai & Sinh nở giải đáp mọi thắc mắc liên quan đến quá trình người mẹ thụ thai, mang thai và sinh nở cho đến khi bé được sáu tuần tuổi. Qua quyển sách này, tác giả cũng giúp người mẹ làm quen với những gì họ sẽ trải qua khi sắp sinh: những giai đoạn chuyển dạ, cách rặn đẻ, các kỹ thuật đặc biệt khác. Người mẹ cũng được hướng dẫn cách chăm sóc, phục hồi cơ thể cho chính mình, cũng như chuẩn bị tâm lý cho một gia đình mới sau khi sinh. Sách cũng là một trợ lý đắc lực cho các bậc cha mẹ khi cần mua sắm những vật dụng cần thiết để cho quá trình mang thai cũng như sau khi sinh nở.', '2020-03-07', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_20378.jpg', 50),
    (11, 3446, N'Bách khoa Tri Thức Thai Sản Tập 1 - Để Sinh Con Khỏe Mạnh & Thông Minh', N'NXB Văn học', 25160.00, N'Chương I: Chuẩn bị trước khi mang thai 1. Những tri thức cơ bản về sinh đẻ 2. Chuẩn bị trước khi mang thai 3. Các phương pháp trị liệu với bệnh vô sinh Chương II: Sinh đẻ tốt và nuôi dưỡng tốt 1. Những tri thức cơ bản để sinh đẻ tốt 2. Duy truyền và việc sinh đẻ tốt 3. Các biện pháp tránh thai Chương III: Sức khỏe sinh lý thời kỳ mang thai 1. Những kiến thức cơ bản về việc mang thai 2. Những thay đổi trong thời kỳ mang thai', '2016-06-13', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_20379.jpg', 50),
    (12, 3497, N'Tìm Hiểu Cuộc Đời Qua Khuôn Mặt', N'NXB Thế giới', 125000.00, N'Điều gì sẽ xảy ra nếu chỉ bằng cách nhìn mọi người, bạn có thể biết được khuynh hướng suy nghĩ, cảm nhận và cư xử của họ? Điều gì sẽ xảy ra nếu khuôn mặt của người bạn đời tiết lộ biện pháp hiệu quả nhất để giải quyết mọi mâu thuẫn có thể nảy sinh giữa hai vợ chồng bạn? Và điều gì sẽ xảy ra nếu bạn có thể khám phá trên khuôn mặt mình những thông tin cần thiết để sống thật với chính mình?', '2023-01-26', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786048557089_1.jpg', 50),
    (13, 3523, N'Tử Vi Đẩu Số Thuật Đăng Hạ -Tập 2', N'NXB Lao Động', 192000.00, N'Là một trong những quốc gia có nền Thiên văn học phát triển sớm nhất và nhanh chóng nhất trên thế giới, Trung Quốc ngay từ thời nguyên thuỷ đã manh nha những mầm mong đầu tiên của Thiên văn học cổ đại. Vào thời Đế Nghiêu đã thiết lập nên chức quan chuyên cai quản về Thiên văn, trong những di chỉ của văn hoá Ngưỡng Thiều (Văn hóa đồ đá mới Trùng Quốc, cách đây khoảng 7000-5000 năm), đã xuất hiện hình vẽ mặt trời cùng những đốm đen trên đó. Trong khoảng thời gian từ thế kỷ 2 đến thế kỷ 15, nền Thiên văn học châu Âu phát triển rất chậm chạp, thậm chí còn đình trệ, dậm chân tại chỗ suốt hơn 1000 năm, trong khi đó nền Thiên văn học của Trung Quốc vẫn tiếp tục phát triển ổn định, và đạt được nhiều thành tựu huy hoàng. Rất nhiều thành tựu rực rỡ về Thiên văn học có mối quan hệ hết sức mật thiết với Đạo giáo. Nhận thức của Đạo giáo vể sự hình thành của vũ trụ, cách phân tích của họ về các giai đoạn trong quá trình tiến hoá của vũ trụ đã đem lại cho người Trung Quốc vốn kiến thức về vũ trụ, hình thành những mầm mong của vũ trụ học. Cách giải thích của Đạo giáo đối với kết cấu của vũ trụ (thuyết hỗn thiên), những thành quả nghiên cứu của họ về lĩnh vực lịch toán, vật lý học thiên văn cùng hiện tượng nhật thực, nguyệt thức và thực nghiệm quang học, đều giữ vị trí đi đầu trong lịch sử thiên văn học Thế giới. Hiện nay, các thành tựu quan trọng về thiên văn lịch toán của Đạo giáo phần nhiều đã được tập hợp trong bộ tổng tập kinh điển của Đạo gia - "Đạo tạng". "Đạo tạng” được biên soạn lần đầu tiên vào niên hiệu Khai Nguyên thời Đường, trải qua quá trình tăng biên, hiệu đính trong suốt các triều đại Tống, Kim, Nguyên, Minh, nội dung của bộ sách không ngừng được tăng bổ và hoàn thiện, trở thành tập đại thành của các kinh điển Đạo gia. Trong "Đạo tạnự còn tập hợp khá nhiều những trước tác về khoa học kỹ thuật cổ đại của Trung Quốc, nên đây chính là nguồn sử liệu quan trọng để nghiên cứu về các lĩnh vực y dược học, dưỡng sinh học, hoá học, thiên văn học, lịch pháp, khí công, nội ngoại đan, khoa học cơ thể người. Những ghi chép về lĩnh vực thiên văn lịch toán trong tác phẩm này vẫn luôn là một nội dung thần bí nhất, giàu giá trị khoa học nhất trong bộ tổng tập. Trong tất cả những nội dung về thiên văn lịch toán ghi chép trong "Đạo tạng“, nội dung đặc sắc nhất chính là chiêm tinh học (tinh tượng học). Trong "Đạo tạng" không chỉ ghi chép về chiêm tinh học vật lý, mà còn kết hợp chiêm tinh với giáo nghĩa của Đạo giáo, để sáng tạo nên chiêm tinh học chính kinh, chiêm tinh học nhân văn và chiêm tinh học thời sự. Trong số các kinh điển lịch số, chỉ có môn Tử Vi Đẩu số là có thể áp dụng thiên văn vào trong đời sống, dùng chiêm tinh để suy đoán việc người, dung hợp và thống nhất nhiều chủng loại chiêm tinh học khác nhau. Từ khi được sáng lập bởi Trần Đoàn (Trần Hy Di) - một nhân vật quan trọng của Đạo gia, sống dưới thời Bắc Tống - cho đến những giai đoạn phát triển tiếp theo, Tử Vi Đẩu số vẫn luôn là một nhánh có lịch sử lâu dài, cơ sở vững chắc, hệ thống hoàn bị và suy đoán tinh xác nhất trong hệ thống thiên văn lịch toán học cổ đại và mệnh lý học truyền thống, nên đã giành được vị trí đầu bảng trong "ngũ đại thần số". Bộ môn này dựa trên cơ sở lý luận là hệ thống thiên can, địa chi, âm dương, ngũ hành, tiếp thu rộng rãi các kiến thức về thiên văn học, lịch toán học, sử học, thống kê học, toán học phân số, dự đoán học cổ đại, để tiến hành phân tích về các đặc tính không - thời gian của các vì sao và định vị về mối quan hệ giữa các vì sao và con người, từ đó suy đoán ra các vấn đề nhân văn. Nên đây chính là một lĩnh vực khoa học hết sức bao quát và uyên thâm. Trong một khoảng thời gian rất dài, bộ môn khoa học này vẫn được truyền thừa liên tục trong nội bộ Đạo giáo. Phương thức truyền thừa bí mật và khép kín này một mặt đã tăng cường tính độc lập cho hệ thống lý luận, nhưng mặt khác lại khiến cho nó càng trỗ nên khó hiểu đối với người học "ngoại đạo". Tron g những năm gần đây, tuy Tử Vi Đẩu số ngày càng thu hút được sự chú ý của số đông người đọc, nhưng có rất ít người quan tâm đến việc giải mã những bí ẩn trong lý luận của bộ môn này. Cùng với sự lan toả của làn sóng nghiên cứu Tử Vi Đẩu số rộng rãi khắp các khu vực Trung Hoa, Hồng Kông, Đài Loan và cả khu vực Đông Nam Á, thì yêu cầu giải mã hệ thống lý luận Tử Vi Đẩu số ngày càng trở nên bức thiết. Trong tình hình đó, việc vén lên bức màn bí mật của Tử Vi Đẩu số và tiến hành giải mã những mật mã lý luận này chính là nhiệm vụ mà chúng tôi tự đặt ra cho cuốn sách này.', '2021-08-13', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935088536146_1.jpg', 50),
    (14, 3769, N'Thực Đơn Nấu Ăn Đơn Giản Tập 1', N'NXB Hội nhà văn', 25160.00, N'Mục lục: Thực đơn 1: Chuối tiêu non nấu tôm thịt Đậu ngọt xốt tôm Chả trứng cuộn Thực đơn 2: Canh nghêu nấu mẻ Rau mầm xào mề gà Cá thác lác nhồi hành tây Thực đơn 3: Củ cải nấu sờn Củ hũ dừa cuộn măng tây Cá điêu hồng hấp nước tương Thực đơn 4: Bông điên điển nấu tôm Xoài trộn hến Mực nhồi thịt chiên xù Thực đơn 5: Khoai mỡ nấu thịt băm Dưa mắm trộn tỏi ớt Cá lòng tong kho.', '2016-11-11', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935073079054_1.jpg', 50),
    (15, 3837, N'Phong Thủy Trong Nhân Duyên', N'NXB Tổng hợp TP.HCM', 112000.00, N'Phong thủy là tinh hoa trí tuệ ngàn năm của văn hóa phương Đông. Khoa học Phong thủy đã được áp dụng vào cuộc sống hiện đại ngày nay và mang đến những ảnh hưởng tích cực cho chúng ta. Những việc rất nhỏ như sắp xếp, bài trí lại đồ đạc có thể giảm bớt căng thẳng tinh thần, suy nghĩ tiêu cực và những bất hòa trong các mối quan hệ; mang lại niềm vui, hạnh phúc cho mọi người trong gia đình. Cho dù sống ở đâu thì vận mệnh của bạn cũng từng phút từng giây chịu ảnh hưởng của Phong thủy. Và có một điều thú vị là là chúng ta có thể áp dụng phong thủy để loại bỏ những ngăn trở trong tình yêu - thu hút và xây dựng mối nhân duyên tốt đẹp, bền lâu. Phong Thủy Trong Nhân Duyên trình bày những giải pháp phong thủy đơn giản nhưng hiệu quả, giúp bạn có được tình cảm trọn vẹn trong tình yêu và sâu xa hơn nữa là một cuộc hôn nhân hạnh phúc. Sống trong một ngôi nhà có Phong thủy tốt, lại biết vận dụng chính xác các phương thức chiêu Đào hoa thì chẳng khác nào bạn đang nắm trong tay một vũ khí hữu hiệu để thu hút nhiều tình cảm của người khác, tạo ra nhiều cơ hội lựa chọn người bạn đời lý tưởng cho mình. Tuy nhiên, ngay cả Đào hoa cũng có "Đào hoa tốt" và "Đào hoa xấu". Cuộc đời mỗi người không phải hoàn toàn do số mệnh định đoạt, mà một phần không nhỏ là do chính bản thân chúng ta tạo dựng lên. Bởi vậy, chỉ có những ai tự tìm tòi, hiểu biết, và có thiện chí hoàn thiện chính mình thì mới có thể nắm giữ được những đóa hoa Đào đẹp nhất cho mình. Cho nên cuốn sách có thể là một gợi ý để bạn trở thành một con người có số "đào hoa tốt". Cuốn sách do Giáo sư Tạ Nguyên Cẩn tổng hợp và biên soạn từ những kiến thức Phong thủy uyên bác và kinh nghiệm thực tiễn phong phú. Với bố cục mạch lạc, lối hành văn khúc chiết, dễ hiểu, kết hợp với những hình ảnh minh họa thực tế… tác giả sẽ chỉ ra cho bạn những phương pháp hiệu quả nhất, triệt để nhất để nhận biết và loại bỏ những gì cản trở tình duyên. Ngoài ra những bảng biểu đối chiếu rõ ràng, những câu chuyện sinh động cũng giúp bạn xây dựng được một môi trường sống hài hòa, trở nên "có duyên" hơn, thu hút được nhiều may mắn trong tình yêu và hôn nhân. Cuốn sách cung cấp những hiểu biết cơ bản về đào hoa trong nhân duyên, cách thức nhận biết và tìm hiểu vận thế đào hoa của một người. Theo đó, địa điểm thu hút đào hoa của một người là tại nơi người ta thường xuyên sống ở đó. Tất cả các biện pháp thu hút Đào hoa (chiêu Đào hoa) đến vị trí Đào hoa Sinh tiêu nhất thiết chỉ được tiến hành trong phạm vi này. Nếu không, dễ xảy ra tình trạng không thu hút được Đào hoa của mình mà lại thu hút phải Đào hoa của một người khác cũng sống trong ngôi nhà ấy. Ngoài ra, nội dung sách còn đề cập đến các nguyên tắc bảo vệ vị trí đào hoa như cách thức sắp đặt đồ đạc và quần áo, cách trang trí một bình hoa, màu sắc, hình dáng của bình hoa (cả loại hoa cắm trong bình cũng phải được lựa chọn cho phù hợp). Hướng mở cửa, góc độ khép - mở cửa, cách phối hợp các vật thủy tinh trang trí với màu sắc, kích thước khác nhau cũng ảnh hưởng đến số mệnh đào hoa của thân chủ. Và đặc biệt hơn cả là để có một cuộc hôn nhân tốt đẹp, còn phải chú ý xem xét tuổi tác cho mối nhân duyên, thời gian kết hôn, kết cấu và cách bài trí trong phòng ngủ... Hy vọng cuốn sách sẽ đưa lại cho bạn những những tri thức hữu ích nhất về Phong thủy Mệnh lý , giúp bạn có điều kiện và cơ hội tìm được một hạnh phúc thật viên mãn, tròn đầy!', '2022-12-10', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935086813096_1.jpg', 50),
    (16, 4664, N'Hiểu Biết Để Phòng Và Trị Bệnh Tim Mạch', N'NXB Phụ nữ', 48000.00, N'Hiểu Biết Để Phòng Và Trị Bệnh Tim Mạch "Từ phát hiện sớm đến trị sớm các bệnh tim mạch đã được nhiều thầy thuốc nội ngoại khoa tim mạch quan tâm từ trên hai thế kỷ nay.Gần đây đã có nhiều công trình nghiên cứu, tài liệu, báo chí, phát thanh, truyền hình, hội thảo ở trong nước cũng như ở nước ngoài về chuyên đề các bệnh tim mạch nội ngoại khoa.Nhiều vấn đề mới đã qua nghiên cứu và áp dụng vào thực hành nội ngoại khoa tim mạch như mổ tim hở trong điều kiện tuần hoàn ngoài cơ thể kết hợp với hạ thể nhiệt nhân tạo ở nhiều mức độ khác nhau, can thiệp các bệnh tim mạch không xâm lấn, ghép tim giữa người cho (đã chết não) và người mắc bệnh tim nặng, ghép tim nhân tạo hoạt động song song với trái tim đã và đang bị hư hỏng nặng của người bệnh v.v… Tuy vậy, trong cuộc sống, không phải ai cũng hiểu một cách đầy đủ về trái tim của mình, biết cách bảo vệ và am hiểu để điều trị tích cực nó khi lâm bệnh.Trong cuốn sách nhỏ này, tác giả chỉ muốn giới thiệu với độc giả về chẩn đoán, chỉ định điều trị các bệnh tim mạch bằng phương pháp mổ xẻ, hy vọng những thông tin trong tập tài liệu này sẽ giúp chúng ta hiểu biết, đề phòng và an tâm điều trị nó bằng phương pháp ngoại khoa khi có chỉ định.Phẫu thuật tim và màng ngoài tim là một trong những vấn đề phức tạp và quan trọng nhất trong lĩnh vực mổ xẻ điều trị các bệnh và thương tích ở các cơ quan trong lồng ngực. Lịch sử của phẫu thuật tim đã có từ cuối thế kỷ XIX, khi Block là người đầu tiên tiến hành khâu vết thương tim trong thực nghiệm (1882) và nhà mổ xẻ Đức tên là Ren (1896) đã thành công trong việc đặt mũi khâu đầu tiên trên vết thương tim ở người. Đó là những cuộc mổ tim đầu tiên trên thế giới, đồng thời cũng là bước ngoặt lịch sử trong khoa mổ xẻ nói chung.Từ đó cho tới trên năm chục năm sau (1948), người ta vẫn chỉ mới dám khâu vết thương tim vì cho rằng nếu không khâu thì đằng nào bệnh nhân cũng sẽ chết, còn việc mổ xẻ để điều trị các bệnh tim thì chưa có một ai dám nghĩ tới. Trong thực tế thì bệnh tim gặp nhiều hơn vết thương tim và nhiều bệnh tim không thể chữa khỏi được bằng phương pháp bảo tồn mà cần phải có bàn tay của người bác sĩ mổ xẻ. Do đó, yêu cầu điều trị các bệnh tim bằng phẫu thuật đã trở thành một vấn đề cấp bách. Mặc dù thế, mổ xẻ điều trị các bệnh tim vẫn là một lĩnh vực tương đối mới trong ngành phẫu thuật. Ngành mổ tim mới phát triển cách đây trên 55 năm. Riêng ở Việt Nam mổ xẻ điều trị các bệnh tim được bắt đầu từ năm 1958. Kỹ thuật mổ tim rất đơn giản, nhưng trước kia, những người thầy thuốc chưa dám mở rộng công việc mổ xẻ này vì mấy lý do sau đây: chưa có những phương tiện chẩn đoán tốt và chính xác, kỹ thuật mổ còn ở mức độ thấp, sợ không dám tiến hành các cuộc mổ xẻ trên một cơ quan quan trọng như trái tim, sợ tim có thể ngừng đập trong khi mổ do choáng phản xạ, sợ mở màng phổi sẽ bị nhiễm trùng xoang màng phổi, v.v.., chưa có tổ chức và phương tiện gây mê hồi sức tốt. Kết quả mổ xẻ chủ yếu phụ thuộc vào các điều kiện kể trên và vào tình trạng toàn thân của bệnh nhân trước khi mổ. Hiện nay nhờ có những máy móc và những phương pháp hiện đại để chẩn đoán bệnh tim, như thông tim để đo áp lực trong các buồng tim, định lượng dưỡng khí (O2) và thán khí (CO2) của máu lấy từ trong các buồng tim ra, chụp X quang cản quang các buồng tim, ghi điện tim, ghi siêu âm tim để đánh giá tình trạng các van tim, ghi âm thanh tim, v.v.. và những máy móc để thực hiện gây mê hồi sức với trình độ kỹ thuật cao, nên ta đã mổ xẻ được nhiều bệnh tim phức tạp với kết quả tốt như bệnh hẹp hở các van tim, các dị tật bẩm sinh ở trong tim và các mạch máu lớn gần tim, bệnh thiếu máu cơ tim, bệnh viêm màng ngoài tim có mủ hoặc co thắt, v.v.. Áp dụng phương pháp hạ thể nhiệt nhân tạo và tuần hoàn ngoài cơ thể (bằng sử dụng máy tim-phổi nhân tạo) đã tạo điều kiện thuận lợi cho việc mổ xẻ điều trị các bệnh tim mắc phải và bẩm sinh phức tạp trên "tim khô", nghĩa là trên một quả tim đã được làm ngừng đập hoàn toàn bằng một máy đặc biệt gọi là máy tạo rung tim, hoặc bằng một dung dịch đặc biệt ở nhiệt độ thấp bơm vào hệ thống động mạch vành tim để làm cho tim ngừng đập. Khi đó máu không chảy vào tim và không làm cản trở các hoạt động của người thầy thuốc trong lúc mổ xẻ sửa chữa những tổn thương bệnh lý ở trong tim như vá kín những lỗ thông giữa các buồng tim bên trái và bên phải, sửa thay các van tim bị hư hỏng hoàn toàn bằng các van tim nhân tạo, bắc cầu nối giữa động mạch chủ và động mạch vành tim trong bệnh thiếu máu cơ tim, v.v.. Sau khi mổ xong, ta hâm nóng máu trong máy tim-phổi nhân tạo bằng một bộ phận sưởi ấm, truyền dung dịch hâm nóng vào hệ thống động mạch vành tim hoặc dùng máy chống rung tim để làm cho quả tim tự đập lại bình thường. Trong một số trường hợp có biến chứng ngừng tim trong hoặc sau khi mổ do hệ thống dẫn truyền tự động trong tim bị hủy hoại, ta có thể dùng một loại máy đặc biệt để điều chỉnh lại tạm thời hay thường xuyên nhịp đập của tim gọi là máy tạo nhịp tim.Khoa mổ xẻ điều trị các bệnh tim còn đang trên đà tiến triển. Người ta đã thay quả tim của người bị bệnh tim nặng bằng quả tim của nạn nhân bị chết vì một tai nạn bất ngờ. Tuy vậy, kể cả việc ghép tim trên người cũng chưa phải là cái đỉnh cao nhất của khoa học y học trong việc điều trị các bệnh tim. Trong tương lai, người ta sẽ ghép thêm cho người bị bệnh tim nặng một quả tim nhân tạo và quả tim này sẽ hoạt động song song với quả tim của người bệnh. Chúng tôi hy vọng rằng cuốn sách Hiểu biết để phòng và trị bệnh tim mạch sẽ giúp bạn đọc, kể cả bạn đọc không công tác trong ngành y tế hiểu biết về quả tim của mình, bảo vệ nó như thế nào, về một số bệnh tim thường gặp, những biện pháp đề phòng và các phương pháp điều trị những bệnh đó. Cuốn sách nhỏ này cũng giúp bạn đọc hiểu thêm về những thành tựu to lớn của khoa mổ tim trên thế giới nói chung và ở Việt Nam nói riêng.Tuy nhiên, cuốn sách khó tránh khỏi những thiếu sót nhất định. Chúng tôi luôn hoan nghênh những ý kiến đóng góp xây dựng của bạn đọc và xin chân thành cảm ơn các bạn." TP. Hồ Chí Minh, mùa xuân 2012 Tác giả', '2021-10-20', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786045803226_1.jpg', 50),
    (17, 5492, N'Our Discovery Island American Picture Cards 5', N'NXB Trẻ', 1057000.00, N'Welcome to Our Discovery Island, a six-level primary series that engages children in 21st century learning. Children uncover clues and solve mysteries as they learn English. Our Discovery Island is a groundbreaking new course that makes learning English an exciting and engaging experience.', '2021-09-13', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9781447900399_1.jpg', 50),
