USE BookStore;
GO

-- Đảm bảo kiểu dữ liệu bảng books tương thích độ dài URL và giá bán
IF COL_LENGTH('books', 'cover_image') < 500
    ALTER TABLE books ALTER COLUMN cover_image NVARCHAR(500);
IF COL_LENGTH('books', 'price') < 10
    ALTER TABLE books ALTER COLUMN price DECIMAL(10,2);
GO

-- 1. Dọn sạch dữ liệu cũ và reset IDENTITY
DELETE FROM rating;
DELETE FROM book_author;
DELETE FROM books;
DELETE FROM author;
DBCC CHECKIDENT ('books',  RESEED, 0);
DBCC CHECKIDENT ('author', RESEED, 0);
GO

-- 2. Chèn dữ liệu tác giả (author)
SET IDENTITY_INSERT author ON;
SET IDENTITY_INSERT author OFF;
GO

-- 3. Chèn dữ liệu sách (books)
SET IDENTITY_INSERT books ON;
SET IDENTITY_INSERT books OFF;
GO

-- 4. Chèn quan hệ N-N (book_author)
GO

-- 5. Chèn đánh giá mẫu (rating)
IF EXISTS (SELECT 1 FROM users WHERE id = 1)
BEGIN
END
GO

PRINT N'Dữ liệu từ Fahasa đã được nạp thành công vào Database BookStore!';
GO
